121→
122→    #[test]
123→    fn suppress_notification_sets_env() {
124→        suppress_notification();
125→        assert!(is_notification_suppressed());
126→    }
127→
128→    #[test]
129→    fn install_method_provides_update_command() {
130→        let cargo = InstallMethod::Cargo;
131→        assert!(cargo.update_command().is_some());
132→
133→        let homebrew = InstallMethod::Homebrew;
134→        assert!(homebrew.update_command().is_some());
135→    }
136→
137→    #[test]
138→    fn check_and_prompt_update_non_interactive() {
139→        let mut ui = MockUI::new();
140→        // MockUI is non-interactive, so this should return false
141→        let result = check_and_prompt_update(&mut ui).unwrap();
142→        assert!(!result);
143→    }
144→
145→    #[test]
146→    fn prompt_for_update_with_manual_install() {
147→        let mut ui = MockUI::new();
148→        let info = UpdateInfo {
149→            current: "0.1.0".to_string(),
150→            latest: "0.2.0".to_string(),
151→            update_available: true,
152→            release_url: Some("https://github.com/example/releases".to_string()),
153→            checked_at: Utc::now(),
154→        };
155→        let method = InstallMethod::Manual {
156→            path: PathBuf::from("/tmp/bivvy"),
157→        };
158→
159→        let result = prompt_for_update(&mut ui, &info, &method).unwrap();
160→        assert!(!result); // Manual installs don't support auto-update
161→
162→        // Should have shown the download URL
