407→    /// Check if the terminal is indeed a terminal.
408→    #[inline]
409→    pub fn is_term(&self) -> bool {
410→        self.is_tty
411→    }
412→
413→    /// Check for common terminal features.
414→    #[inline]
415→    pub fn features(&self) -> TermFeatures<'_> {
416→        TermFeatures(self)
417→    }
