                    } else {
                        render.input_prompt_selection(&self.prompt, &input)?;
                    }
                }
                term.flush()?;

                return Ok(value);
            }
            Err(err) => {
                render.error(&err.to_string())?;
                continue;
            }
        }
    }
}

