    #[test]
    fn dialoguer_eof_error_converts_to_user_cancelled() {
        let io_err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
        let result: std::result::Result<bool, dialoguer::Error> = Err(io_err.into());
        let mapped = map_dialoguer_result(result);
        assert!(mapped.is_err());
        assert!(matches!(
            mapped.unwrap_err(),
            crate::error::BivvyError::UserCancelled
        ));
    }

    #[test]
    fn dialoguer_other_error_converts_to_io_error() {
        let io_err = std::io::Error::new(std::io::ErrorKind::Other, "some error");
        let result: std::result::Result<bool, dialoguer::Error> = Err(io_err.into());
        let mapped = map_dialoguer_result(result);
        assert!(mapped.is_err());
        assert!(matches!(
            mapped.unwrap_err(),
            crate::error::BivvyError::Io(_)
        ));
    }

    #[test]
    fn dialoguer_ok_result_passes_through() {
        let result: std::result::Result<bool, dialoguer::Error> = Ok(true);
        let mapped = map_dialoguer_result(result);
        assert!(mapped.is_ok());
        assert_eq!(mapped.unwrap(), true);
    }
}

//! Interactive prompts.

use console::{measure_text_width, style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Check if an IO error indicates EOF (e.g., from Ctrl+D).
fn is_eof_error(err: &std::io::Error) -> bool {
    err.kind() == std::io::ErrorKind::UnexpectedEof
}

/// Check if a key is Ctrl+D (byte 0x04 in raw mode).
fn is_ctrl_d(key: &Key) -> bool {
    matches!(key, Key::Char('\x04'))
}

/// Convert a dialoguer result to a BivvyError, mapping EOF to UserCancelled.
fn map_dialoguer_result<T>(result: std::result::Result<T, dialoguer::Error>) -> Result<T> {
    match result {
        Ok(val) => Ok(val),
        Err(e) => {
            let io_err: std::io::Error = e.into();
            if is_eof_error(&io_err) {
                Err(BivvyError::UserCancelled)
            } else {
                Err(BivvyError::Io(io_err))
            }
        }
    }
}

/// Dialoguer theme without the default yellow `?` prefix.
fn prompt_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        ..ColorfulTheme::default()
    }
}

/// Prompt the user for input.
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    match &prompt.prompt_type {
        PromptType::Confirm => prompt_confirm(prompt, term),
        PromptType::Input => prompt_input(prompt, term),
        PromptType::Select { options } => prompt_select(prompt, options, term),
        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
    }
}

fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let default = prompt
        .default
        .as_ref()
        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
        .unwrap_or(true);

    let result = map_dialoguer_result(
        Confirm::new()
            .with_prompt(&prompt.question)
            .default(default)
            .interact_on(term),
    )?;

    Ok(PromptResult::Bool(result))
}

fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let input = Input::<String>::new().with_prompt(&prompt.question);

    let result: String = if let Some(default) = &prompt.default {
        map_dialoguer_result(input.default(default.clone()).interact_on(term))?
    } else {
        map_dialoguer_result(input.interact_on(term))?
    };

    Ok(PromptResult::String(result))
}

